@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🏷分类",null,1,1)
push("最近🏷更新",`/update`,1,1)
push("新书🏷发布",`/update/newbook`,1,0.35)
push("推荐🏷漫画",`/update/recommend`,1,0.35)
nrList=[["全部","all"],["已完结","completed"],["连载中","serialized"]]
	arList=["正妹","恋爱","出版漫画","肉慾","浪漫","大尺度","巨乳","有夫之婦","女大生","狗血劇","同居","好友","調教","动作","後宮","不倫","3D","校園","耽美","日漫"]
	nrList.map([title,ure]=>{
		push(title,`/comics/all/ob/time/st/${ure}`,1,1);
	arList.map((tag)=>{
		url=`/comics/${tag}/ob/time/st/${ure}/page/{{page}}`;
				push(tag, url, 1, 0.25);
		});
		});
		push("榜🏷单",null,1,1)
		mrList=[["周榜","weekly"],["月榜","monthly"],["日榜","daily"],["总榜","all"]]
		mrList.map([tag,uri]=>{
			url=`/ranking/${uri}`;
			push(tag,url,1,0.25)
			});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

