    return P[e];
}
function p(e) {
    if (p == undefined) {
        p = result.p;
    }
    if (e == $$$.p) {
        return login('【排序切换提示】' + n(2) + '已经选择此排序，无需更换');
    }
    login('【排序切换提示】' + n(2) + '已经切换到[' + typeP(e) + ']排序');
    $$$.p = e;
    return put($$$);
}
function search_TC() {
    if (search_TC == undefined) {
        search_TC = true;
    }
    if ($$$.search_TC == true) {
        login('【繁体搜索提示】' + n(2) + '已关闭繁体搜索，请重新搜索');
        $$$.search_TC = false;
        put($$$);
    } else {
        login('【繁体搜索提示】' + n(2) + '已开启繁体搜索，请重新搜索');
        $$$.search_TC = true;
        put($$$);
    }
}
function TC_to_SC() {
    if (TC_to_SC == undefined) {
        TC_to_SC = true;
    }
    if ($$$.TC_to_SC == true) {
        login('【简繁转换提示】' + n(2) + '已关闭繁体转换，请刷新书籍');
        $$$.TC_to_SC = false;
        put($$$);
    } else {
        login('【简繁转换提示】' + n(2) + '已开启繁体转换，请刷新书籍');
        $$$.TC_to_SC = true;
        put($$$);
    }
}
function settle() {
    if (settle == undefined) {
        settle = true;
    }
    if ($$$.settle == true) {
        login('【目录整理提示】' + n(2) + '已关闭目录整理，请刷新目录');
        $$$.settle = false;
        put($$$);
    } else {
        login('【目录整理提示】' + n(2) + '已开启目录整理，请刷新目录');
        $$$.settle = true;
        put($$$);
    }
}

